        .With("Positive", m_PositiveKeyboardBinding)
        .With("Negative", m_NegativeKeyboardBinding);

    if (!string.IsNullOrEmpty(m_PositiveGamepadBinding) && !string.IsNullOrEmpty(m_NegativeGamepadBinding))
    {
